"""Swift: a Swift package. Swift reads the C headers itself (CRaven); Raven adds a few helpers."""

from cparse import SKIPPED_HEADERS


def headers(api):
    """The headers of the API, in the order of Raven.h, without the ones only C uses."""
    order = []
    for function in api.functions:
        if function.header not in order and function.header not in SKIPPED_HEADERS:
            order.append(function.header)
    return order


PACKAGE = '''// swift-tools-version:5.9
// Raven for Swift. Generated by tools/bindgen (Raven %(version)s): do not edit.
//
// Set RAVEN_LIB_DIR to the folder that holds the library (libraven.dylib,
// libraven.so) when it is not where the linker looks by itself:
//
//   RAVEN_LIB_DIR=/path/to/lib swift run hello
//
// The package can also be used without it: swift build -Xlinker -L/path/to/lib

import PackageDescription

var linkerSettings: [LinkerSetting] = []
if let dir = Context.environment["RAVEN_LIB_DIR"], !dir.isEmpty {
    // (the rpath lets the program find the library when it starts)
    linkerSettings.append(.unsafeFlags(["-L" + dir, "-Xlinker", "-rpath", "-Xlinker", dir]))
}

let package = Package(
    name: "Raven",
    products: [
        .library(name: "Raven", targets: ["Raven"]),
    ],
    targets: [
        // the C API as it is, read by Swift from the headers of include/
        .systemLibrary(name: "CRaven", path: "Sources/CRaven"),
        // the C API again, and helpers for closures and texts
        .target(name: "Raven", dependencies: ["CRaven"], linkerSettings: linkerSettings),
        // a window described in XML; --test runs it without a window system and without a GPU
        .executableTarget(name: "hello", dependencies: ["Raven"], path: "Examples/hello"),
    ]
)
'''

MODULEMAP = '''// The C API of Raven for Swift. Generated by tools/bindgen: do not edit.
module CRaven [system] {
    header "raven_swift.h"
    link "raven"
    export *
}
'''

SHIM = '''/* The headers of Raven that Swift imports (CRaven). Generated by tools/bindgen: do not edit.
 *
 * Raven.h without raven_backend.h and raven_vulkan.h, which only make sense
 * from C. The paths lead to include/ of the repository. */
#ifndef RAVEN_SWIFT_H
#define RAVEN_SWIFT_H

%(includes)s

/* Swift cannot read ((Rid)-1): the same value, as a constant it reads */
#undef R_INVALID_ID
static const Rid R_INVALID_ID = (Rid)-1;

#endif
'''

RAVEN_SWIFT = '''// Raven for Swift.
//
// Generated from the C headers by tools/bindgen (Raven %(version)s): do not edit.
//
// `import Raven` gives the C API as it is, read by Swift from the headers: the
// same names, the same documentation, Swift strings where C takes a text
// (`Rlabel_set_text(label, "Hi")`), `inout` where it takes a pointer to a value.
// Around it, a few helpers for what Swift does differently from C:
//
// - `text` reads a text of the library;
// - `actionBind`, `timerStart` and `errorSetCallback` take closures;
// - `windowFromXml` and `widgetFromXml` take a `String`.
//
//     import Raven
//
//     Rinit(R_BACKEND_VULKAN)
//     let window = windowFromXml(#"<Window Title="Hi"><Button Text="Quit" OnClicked="quit"/></Window>"#)
//     actionBind("quit") { _, _ in Rquit(0) }
//     while Rwait_frame(-1) != 0 {}
//     Rshutdown()
//
// Raven belongs to the thread that starts it: call it, and these helpers, from
// that thread only.

@_exported import CRaven

/// A text of the library as a `String` ("" for a null pointer).
public func text(_ pointer: UnsafePointer<CChar>?) -> String {
    guard let pointer = pointer else { return "" }
    return String(cString: pointer)
}

/// A text of the library as a `String` ("" for a null pointer).
public func text(_ pointer: UnsafeMutablePointer<CChar>?) -> String {
    return text(UnsafePointer(pointer))
}

/// The text held by a fixed array of a structure (`char message[256]`, a tuple in Swift).
public func text<T>(fixed array: T) -> String {
    return withUnsafeBytes(of: array) { bytes in
        let end = bytes.firstIndex(of: 0) ?? bytes.count
        return String(decoding: bytes[..<end], as: UTF8.self)
    }
}

private final class RavenAction {
    let function: (Rid, String) -> Void
    init(_ function: @escaping (Rid, String) -> Void) { self.function = function }
}

private final class RavenTimer {
    let function: () -> Void
    let repeating: Bool
    init(_ function: @escaping () -> Void, _ repeating: Bool) {
        self.function = function
        self.repeating = repeating
    }
}

// what the closures given to the library are kept alive by
private var ravenActions: [String: RavenAction] = [:]
private var ravenTimers: [Rid: RavenTimer] = [:]
private var ravenErrorHandler: ((RError, RSeverity, String) -> Void)?

/// Binds an action (`OnClicked="name"` in XML, `Rwidget_set_action`) to a
/// closure, which receives the widget that fired it and the name of the action.
/// Binding the name again replaces the closure.
public func actionBind(_ name: String, _ function: @escaping (_ sender: Rid, _ action: String) -> Void) {
    let action = RavenAction(function)
    ravenActions[name] = action
    Raction_bind(name, { sender, name, userData in
        guard let userData = userData else { return }
        Unmanaged<RavenAction>.fromOpaque(userData).takeUnretainedValue().function(sender, text(name))
    }, Unmanaged.passUnretained(action).toOpaque())
}

/// Removes the closure of an action (`Raction_unbind`).
public func actionUnbind(_ name: String) {
    Raction_unbind(name)
    ravenActions[name] = nil
}

/// Calls a closure after `seconds`, once or again and again (`Rtimer_create`).
/// Stop it with `timerStop`.
@discardableResult
public func timerStart(_ seconds: Double, repeating: Bool = false, _ function: @escaping () -> Void) -> Rid {
    let timer = RavenTimer(function, repeating)
    let id = Rtimer_create(seconds, repeating ? 1 : 0, { id, userData in
        guard let userData = userData else { return }
        let timer = Unmanaged<RavenTimer>.fromOpaque(userData).takeUnretainedValue()
        timer.function()
        // a timer that fires once is done with its closure
        if !timer.repeating && ravenTimers[id] === timer { ravenTimers[id] = nil }
    }, Unmanaged.passUnretained(timer).toOpaque())
    if id != R_INVALID_ID { ravenTimers[id] = timer }
    return id
}

/// Stops a timer started with `timerStart`.
public func timerStop(_ timer: Rid) {
    if Rtimer_is_valid(timer) != 0 { Rtimer_destroy(timer) }
    ravenTimers[timer] = nil
}

/// Gives the errors and warnings of the library to a closure; `nil` removes it
/// (`Rerror_set_callback`).
public func errorSetCallback(_ function: ((_ code: RError, _ severity: RSeverity, _ detail: String) -> Void)?) {
    ravenErrorHandler = function
    if function == nil {
        Rerror_set_callback(nil)
    } else {
        Rerror_set_callback({ code, severity, detail in
            ravenErrorHandler?(code, severity, text(detail))
        })
    }
}

/// Creates a window from XML (`Rwindow_create_from_xml`).
public func windowFromXml(_ xml: String) -> Rid {
    return Rwindow_create_from_xml(xml, xml.utf8.count)
}

/// Creates a widget tree from XML (`Rwidget_create_from_xml`).
public func widgetFromXml(_ xml: String) -> Rid {
    return Rwidget_create_from_xml(xml, xml.utf8.count)
}
'''

EXAMPLE = '''// A window described in XML, driven from Swift.
//
//   RAVEN_LIB_DIR=/path/to/lib swift run hello
//
// `swift run hello --test` runs without a window system and without a GPU,
// clicks its own button and checks what happened: it is how the build of
// Raven checks this binding.

import Raven
#if canImport(Darwin)
import Darwin
#elseif canImport(Glibc)
import Glibc
#endif

let xml = """
<Window Title="Raven from Swift" Width="360" Height="200">
    <VBox Spacing="10" Slot.Padding="16">
        <Label Name="title" Text="Hello from Swift" TextSize="20"/>
        <TextInput Name="name" Placeholder="Your name"/>
        <HBox Spacing="8">
            <Button Name="greet" Text="Greet" Style="Primary" OnClicked="greet" Slot.Fill="1"/>
            <Button Text="Quit" OnClicked="quit"/>
        </HBox>
    </VBox>
</Window>
"""

func check(_ condition: Bool, _ what: String, line: Int = #line) {
    if !condition {
        print("swift binding: failed at line \\(line): \\(what)")
        exit(1)
    }
}

// (String.contains(String) needs macOS 13 or Foundation)
func has(_ text: String, _ part: String) -> Bool {
    let bytes = Array(text.utf8), wanted = Array(part.utf8)
    if wanted.count > bytes.count { return false }
    for start in 0...(bytes.count - wanted.count) where bytes[start..<start + wanted.count].elementsEqual(wanted) {
        return true
    }
    return false
}

let test = CommandLine.arguments.contains("--test")
var desc = RInitDesc()
desc.backend = test ? R_BACKEND_NULL : R_BACKEND_VULKAN
desc.headless = test ? 1 : 0
if Rinit_ex(&desc) == 0 {
    print("cannot start Raven")
    exit(1)
}

let window = windowFromXml(xml)
let title = Rwidget_find(window, "title")
let name = Rwidget_find(window, "name")
var clicks = 0

actionBind("greet") { _, _ in
    clicks += 1
    Rlabel_set_text(title, "Hello, \\(text(Rtext_input_get_text(name)))!")
}
actionBind("quit") { _, _ in Rquit(0) }

if !test {
    while Rwait_frame(-1) != 0 {}
    Rshutdown()
    exit(0)
}

Rdraw_frame()
check(text(Rwindow_get_title(window)) == "Raven from Swift", "the title of the window")
check(Rwidget_get_type(title) == R_WIDGET_LABEL, "the type of a widget")
Rtext_input_set_text(name, "Zoé")
var x: Float = 0, y: Float = 0, width: Float = 0, height: Float = 0
Rwidget_get_rect(Rwidget_find(window, "greet"), &x, &y, &width, &height)
check(width > 0 && height > 0, "the button is laid out")
Rwindow_inject_mouse_move(window, x + width / 2, y + height / 2)
Rwindow_inject_mouse_button(window, R_MOUSE_LEFT, 1)
Rwindow_inject_mouse_button(window, R_MOUSE_LEFT, 0)
check(clicks == 1, "the click calls the closure")
check(text(Rlabel_get_text(title)) == "Hello, Zoé!", "the closure changed the label")

// structures, and a mistake described in one
var stats = RMemoryStats()
Rmemory_get_stats(&stats)
check(stats.allocation_count > 0, "a structure filled by the library")
var error = RXmlError()
let broken = "<A><B></A>"
check(Rxml_document_parse(broken, broken.utf8.count, &error) == R_INVALID_ID, "a broken document")
check(error.line == 1, "the line of the mistake")
check(has(text(fixed: error.message), "does not match"), "the message of the mistake")

// documents
let document = Rxml_document_create("VBox")
let root = Rxml_document_get_root(document)
let label = Rxml_node_add_child(root, "Label", -1)
Rxml_node_set_attribute(label, "Text", "a < b")
check(has(text(Rxml_document_to_string(document)), "Text=\\"a &lt; b\\""), "a document written as XML")
let built = Rxml_document_create_widget(document)
check(Rwidget_get_xml_node(Rwidget_get_child(built, 0)) == label, "the widgets of a document")
Rwidget_destroy(built)
Rxml_document_destroy(document)

// a timer, and the errors of the library
var fired = 0
timerStart(0) { fired += 1 }
var errors: [String] = []
errorSetCallback { _, _, detail in errors.append(detail) }
Rwidget_destroy(R_INVALID_ID)
check(!errors.isEmpty, "the error callback")
errorSetCallback(nil)
for _ in 0..<10 where fired == 0 { Rdraw_frame() }
check(fired == 1, "the timer")

Raction_fire("quit", R_INVALID_ID)
check(Ris_running() == 0, "an action fired by its name")
Rshutdown()
print("swift binding: ok")
'''

README = '''# Raven for Swift

A Swift package: `import Raven` gives the whole C API of Raven, read by Swift
from the headers of `include/` (the same names and the same documentation as
in C), and a few helpers for closures and texts.

Generated by `tools/bindgen` (`gen_swift.py`): do not edit these files, edit
the generator.

## Use

Build the shared library of Raven (`cmake -B build -DRAVEN_BUILD_SHARED=ON`,
`cmake --build build`), then add the package to yours by its path:

```swift
// Package.swift
dependencies: [
    .package(path: "<raven>/bindings/swift"),
],
targets: [
    .executableTarget(name: "App", dependencies: [.product(name: "Raven", package: "swift")]),
]
```

and tell the linker where the library is:

    RAVEN_LIB_DIR=/path/to/lib swift run

(`RAVEN_LIB_DIR` also gives the program an rpath to the library; without it,
`swift build -Xlinker -L/path/to/lib` and put the library where the program
finds it.)

The example of this folder:

    RAVEN_LIB_DIR=/path/to/lib swift run hello           # a window
    RAVEN_LIB_DIR=/path/to/lib swift run hello --test    # no window system, no GPU: what ctest runs

## From Swift

```swift
import Raven

Rinit(R_BACKEND_VULKAN)
let window = windowFromXml("""
    <Window Title="Hello" Width="320" Height="160">
        <VBox Spacing="10" Slot.Padding="16">
            <TextInput Name="name" Placeholder="Your name"/>
            <Button Text="Greet" Style="Primary" OnClicked="greet"/>
        </VBox>
    </Window>
    """)
let name = Rwidget_find(window, "name")
actionBind("greet") { _, _ in print("Hello,", text(Rtext_input_get_text(name))) }
while Rwait_frame(-1) != 0 {}
Rshutdown()
```

- **Texts.** A Swift `String` goes wherever C takes a `const char*`
  (`Rlabel_set_text(label, "Hi")`). A text of the library comes back as a
  pointer: `text(pointer)` makes it a `String`, and `text(fixed:)` reads a
  `char` array of a structure (a tuple in Swift).
- **Pointers to values** are `inout`: `Rwidget_get_rect(id, &x, &y, &w, &h)`.
- **Structures** start zeroed with `RInitDesc()`.
- **Enumerations** keep their C names (`R_BACKEND_NULL`, `R_WIDGET_LABEL`)
  and compare with `==`.
- **Callbacks.** A C callback takes a closure that captures nothing. To give a
  closure that does, use `actionBind`, `timerStart` (stopped by `timerStop`)
  or `errorSetCallback`; the closures are kept until they are replaced.
  For other callbacks, bind an action (`OnClicked="name"` in XML,
  `Rwidget_set_action`), or pass a context through their `user_data`
  (`Unmanaged.passRetained(object).toOpaque()`).
- **Threads.** Raven belongs to the thread that starts it: call it from that
  thread only.

`raven_backend.h` and `raven_vulkan.h` are left out, as in the other bindings.

Tested on macOS and Linux (Swift 5.9 or later). Windows is not tested.
'''

GITIGNORE = '''.build/
.swiftpm/
Package.resolved
'''


def generate(api):
    version = api.version or "0.2"
    includes = "\n".join('#include "../../../../include/raven/%s"' % h for h in headers(api))
    return {
        "swift/Package.swift": PACKAGE % {"version": version},
        "swift/Sources/CRaven/module.modulemap": MODULEMAP,
        "swift/Sources/CRaven/raven_swift.h": SHIM % {"includes": includes},
        "swift/Sources/Raven/Raven.swift": RAVEN_SWIFT % {"version": version},
        "swift/Examples/hello/main.swift": EXAMPLE,
        "swift/README.md": README,
        "swift/.gitignore": GITIGNORE,
    }
